--------------------------------------------------------------------------------
-- MelloUI - Voice Over
--
-- Reads NPC dialog aloud with the client's built in text-to-speech: gossip
-- greetings, quest offers, progress and turn-in text. Speech keeps playing
-- after the window is closed, so you can accept a quest and walk off while the
-- NPC is still talking.
--
-- Voices come from the operating system (the same ones the chat text-to-speech
-- accessibility feature uses). The NPC's race and gender are looked up in
-- Media\NPCVoiceData.lua (generated by Tools\extract_npc_voices.py) and
-- Media\NPCVoiceOverrides.lua (hand written). Any race group can be given its
-- own text-to-speech voice; NPCs missing from the data fall back to the gender
-- voices. Every text-to-speech line is read at the one Speed setting (the
-- race pitch and speed profiles are gone, 0.15.0: a recorded clip cannot be
-- sped up, so they only ever shaped text-to-speech).
--
-- The voice pack (MelloUI_VoicePack, a separate download: one voice per NPC
-- for all of its lines) plays its recorded line instead of text-to-speech
-- whenever it has one; see "The voice pack". It replaces the old packs
-- (MelloUI_VoiceOverData, AI_VoiceOverData_Vanilla): those are read only
-- while it is not installed, and never beside it.
--
-- Commands: /vo stop, /vo pause, /vo skip, /vo read, /vo test, /vo voices, /vo npc,
-- /vo packs (what loaded, the last lookups), /vo lines, /vo reset
--------------------------------------------------------------------------------

local ADDON_NAME, ns = ...
local MelloUI = ns.MelloUI
-- frames made in a game window: Core's maker, so the game's gamepad
-- navigation never walks an open window for each one (MelloUI.Safe.CreateFrame)
local CreateFrame = MelloUI.Safe.CreateFrame
local Perf = MelloUI.Perf:Scope("VoiceOver")
local C_Timer = Perf.C_Timer

local AUTO_VOICE = -1

-- Filled from C_VoiceChat.GetTtsVoices(); the config dropdowns read this table
-- lazily, so refilling it in place is enough to refresh the list.
local VOICE_VALUES = { { value = AUTO_VOICE, label = "Automatic (by gender)" } }

-- Race groups that can be given their own voice in the settings.
local RACE_GROUPS = {
	{ key = "human",   name = "Humans",            races = { human = true } },
	{ key = "elf",     name = "Elves",             races = { nightelf = true, highelf = true } },
	{ key = "dwarf",   name = "Dwarves",           races = { dwarf = true } },
	{ key = "gnome",   name = "Gnomes",            races = { gnome = true } },
	{ key = "orc",     name = "Orcs",              races = { orc = true } },
	{ key = "troll",   name = "Trolls",            races = { troll = true } },
	{ key = "tauren",  name = "Tauren",            races = { tauren = true } },
	{ key = "undead",  name = "Undead",            races = { undead = true } },
	{ key = "goblin",  name = "Goblins",           races = { goblin = true } },
	{ key = "ogre",    name = "Ogres & Giants",    races = { ogre = true, giant = true } },
	{ key = "monster", name = "Monsters & Beasts", races = nil },  -- everything else
}

local function GroupForRace(race)
	for _, group in ipairs(RACE_GROUPS) do
		if group.races and group.races[race] then
			return group
		end
	end
	return RACE_GROUPS[#RACE_GROUPS]
end

