--------------------------------------------------------------------------------
-- Helpers
--------------------------------------------------------------------------------

-- secret-safe reads, one set for the addon (MelloUI.Safe, Core.lua)
local IsSecret = MelloUI.Safe.IsSecret

local function IsPlainNumber(v)
	return type(v) == "number" and not IsSecret(v)
end

local function HasTTS()
	return C_VoiceChat and C_VoiceChat.SpeakText and C_VoiceChat.GetTtsVoices
end

local function Clamp(v, lo, hi)
	if v < lo then return lo end
	if v > hi then return hi end
	return v
end

local FEMALE_HINTS = { "zira", "hazel", "susan", "heera", "catherine", "linda", "eva", "female", "aria", "jenny", "sonia", "natasha", "libby", "sara", "hedda", "helena", "julie", "irina", "hortense", "elsa", "maria", "hoda", "ayumi", "haruka", "huihui", "yaoyao", "tracy", "michelle", "emma", "ana", "clara", "sofia", "olivia", "amber", "ashley", "cora", "elizabeth", "jane", "monica", "nancy", "zoe" }

local function LooksFemale(name)
	name = (name or ""):lower()
	for _, hint in ipairs(FEMALE_HINTS) do
		if name:find(hint, 1, true) then
			return true
		end
	end
	return false
end

local voices = {}          -- list of { voiceID, name }
local voiceByID = {}       -- [voiceID] = name

local function RefreshVoices()
	wipe(voices)
	wipe(voiceByID)
	for i = #VOICE_VALUES, 2, -1 do
		VOICE_VALUES[i] = nil
	end
	if not HasTTS() then
		return
	end
	local ok, list = pcall(C_VoiceChat.GetTtsVoices)
	if not ok or type(list) ~= "table" then
		return
	end
	for _, voice in ipairs(list) do
		if IsPlainNumber(voice.voiceID) and type(voice.name) == "string" then
			voices[#voices + 1] = { voiceID = voice.voiceID, name = voice.name }
			voiceByID[voice.voiceID] = voice.name
			VOICE_VALUES[#VOICE_VALUES + 1] = { value = voice.voiceID, label = voice.name }
		end
	end
end

local function AutoVoice(female)
	if #voices == 0 then
		return nil
	end
	for _, voice in ipairs(voices) do
		if LooksFemale(voice.name) == female then
			return voice.voiceID
		end
	end
	return voices[1].voiceID
end

local function ChosenVoice(key)
	local chosen = M.db[key]
	if chosen ~= nil and chosen ~= AUTO_VOICE and voiceByID[chosen] then
		return chosen
	end
	return nil
end

local function PickVoice(race, female)
	if race then
		local group = GroupForRace(race)
		local voice = ChosenVoice("voice_" .. group.key)
		if voice then
			return voice
		end
	end
	return ChosenVoice(female and "femaleVoice" or "maleVoice") or AutoVoice(female)
end

--------------------------------------------------------------------------------
-- NPC lookup
--------------------------------------------------------------------------------

local npcLookup = nil   -- [npcID] = { race = string, gender = "m" | "f" | "n" }

local function BuildLookup()
	npcLookup = {}
	if type(MelloUI_NPCVoiceData) == "table" then
		for key, ids in pairs(MelloUI_NPCVoiceData) do
			local race, gender = tostring(key):match("^(%a+)_(%a)$")
			if race and type(ids) == "string" then
				local info = { race = race, gender = gender }
				for id in ids:gmatch("%d+") do
					npcLookup[tonumber(id)] = info
				end
			end
		end
	end
	if type(MelloUI_NPCVoiceOverrides) == "table" then
		for key, entry in pairs(MelloUI_NPCVoiceOverrides) do
			local id = tonumber(key)
			if id and type(entry) == "table" then
				local race = entry.race or entry[1]
				local gender = entry.gender or entry[2]
				if type(race) == "string" then
					npcLookup[id] = { race = race:lower(), gender = type(gender) == "string" and gender:sub(1, 1):lower() or "n", override = true }
				end
			end
		end
	end
end

local function NPCIDFromUnit(unit)
	local ok, guid = pcall(UnitGUID, unit)
	if not ok or type(guid) ~= "string" or IsSecret(guid) then
		return nil
	end
	local id = guid:match("^Creature%-%d+%-%d+%-%d+%-%d+%-(%d+)")
	return id and tonumber(id) or nil
end

local function UnitFemale(unit)
	local ok, sex = pcall(UnitSex, unit)
	if ok and IsPlainNumber(sex) then
		return sex == 3, true
	end
	return false, false
end

local function UnitPlainName(unit)
	local ok, name = pcall(UnitName, unit)
	if ok and type(name) == "string" and not IsSecret(name) then
		return name
	end
	return nil
end

-- Describe the NPC currently being talked to (or targeted, for /vo commands).
local function DescribeNPC(preferTarget)
	if not npcLookup then
		BuildLookup()
	end
	local units = preferTarget and { "target", "npc", "questnpc" } or { "npc", "questnpc", "target" }
	for _, unit in ipairs(units) do
		local ok, exists = pcall(UnitExists, unit)
		if ok and exists then
			local id = NPCIDFromUnit(unit)
			if id then
				local info = npcLookup[id]
				local female, known = UnitFemale(unit)
				local gender
				if info and info.gender ~= "n" then
					female = info.gender == "f"
					gender = info.gender
				elseif known then
					gender = female and "f" or "m"
				else
					gender = info and info.gender or "n"
				end
				return {
					unit = unit,
					id = id,
					name = UnitPlainName(unit),
					race = info and info.race or nil,
					gender = gender,
					female = female,
					source = info and (info.override and "override" or "data") or "unknown",
				}
			end
		end
	end
	return nil
end

--------------------------------------------------------------------------------
-- Text
--------------------------------------------------------------------------------

-- Strip UI escape sequences so the voice does not read colour codes.
local function CleanText(text)
	if type(text) ~= "string" or IsSecret(text) then
		return text
	end
	text = text:gsub("|c%x%x%x%x%x%x%x%x", "")
	text = text:gsub("|r", "")
	text = text:gsub("|T.-|t", "")
	text = text:gsub("|A.-|a", "")
	text = text:gsub("|H.-|h(.-)|h", "%1")
	text = text:gsub("|n", " ")
	text = text:gsub("%s+", " ")
	text = text:gsub("^%s+", ""):gsub("%s+$", "")
	return text
end

-- The text-to-speech rate, in the speech engine's -10..10 units: the Speed
-- setting for every NPC (a stale saved Race Pitch & Speed or Profile Strength
-- is never read).
local function SpeechRate()
	return Clamp(tonumber(M.db.rate) or 0, -10, 10)
end

--------------------------------------------------------------------------------
-- The old sound packs
--
-- The VoiceOver addon's data packs (MelloUI_VoiceOverData, the pack MelloUI
-- offered before MelloUI_VoicePack; AI_VoiceOverData_Vanilla and friends) are
-- load-on-demand addons holding one MP3 per quest line and greeting plus Lua
-- lookup tables. They are loaded here without the VoiceOver player and read
-- directly: quest lines by quest ID, greetings by NPC and text. Only while
-- MelloUI_VoicePack is not installed (Mode below): it replaces them.
--------------------------------------------------------------------------------

local packs = {}            -- { name = addon, data = table, priority = number }
local packsLoaded = false
local packErrors = {}
local TellNewPack           -- forward declaration, defined with the voice pack below
local lookupTrace = {}      -- last few lookup results, for /vo packs
local MAX_TRACE = 8

local function Trace(fmt, ...)
	table.insert(lookupTrace, 1, string.format(fmt, ...))
	lookupTrace[MAX_TRACE + 1] = nil
end
local activeHandle = nil    -- sound handle of the file being played

local function AddOnAPI(name)
	return (C_AddOns and C_AddOns[name]) or _G[name]
end

local function PlainNumber(v)
	return IsPlainNumber(v) and v or nil
end

local function LoadSoundPacks()
	if packsLoaded then
		return
	end
	packsLoaded = true
	local GetNumAddOns, GetAddOnInfo, GetAddOnMetadata = AddOnAPI("GetNumAddOns"), AddOnAPI("GetAddOnInfo"), AddOnAPI("GetAddOnMetadata")
	local IsAddOnLoaded, LoadAddOn = AddOnAPI("IsAddOnLoaded"), AddOnAPI("LoadAddOn")
	if not (GetNumAddOns and GetAddOnInfo and GetAddOnMetadata and IsAddOnLoaded and LoadAddOn) then
		return
	end
	for i = 1, GetNumAddOns() do
		local name = GetAddOnInfo(i)
		local ok, version = pcall(GetAddOnMetadata, name, "X-VoiceOver-DataModule-Version")
		if ok and version then
			-- The pack files expect the VoiceOver player's globals to exist.
			if type(_G.VoiceOver) ~= "table" then
				_G.VoiceOver = {}
			end
			if type(_G.VoiceOver.DataModules) ~= "table" then
				_G.VoiceOver.DataModules = { Register = function() end }
			end
			if type(_G[name]) ~= "table" then
				_G[name] = {}
			end
			local loaded, reason = IsAddOnLoaded(name), nil
			if not loaded then
				-- The packs carry an old interface number; allow out of date
				-- addons just for this load and put the settings back after.
				local prevCheck = GetCVar("checkAddonVersion")
				local prevLast = GetCVar("lastAddonVersion")
				pcall(SetCVar, "checkAddonVersion", 0)
				local _, _, _, interface = GetBuildInfo()
				if prevLast ~= nil and interface then
					pcall(SetCVar, "lastAddonVersion", interface)
				end
				local callOk, a, b = pcall(LoadAddOn, name)
				if prevCheck ~= nil then pcall(SetCVar, "checkAddonVersion", prevCheck) end
				if prevLast ~= nil then pcall(SetCVar, "lastAddonVersion", prevLast) end
				if callOk then
					loaded, reason = a, b
				else
					loaded, reason = false, tostring(a)
				end
			end
			local data = _G[name]
			if loaded and type(data) == "table" and type(data.SoundLengthLookupByFileName) == "table" then
				local _, priority = pcall(GetAddOnMetadata, name, "X-VoiceOver-DataModule-Priority")
				packs[#packs + 1] = { name = name, data = data, priority = tonumber(priority) or 0 }
			else
				packErrors[name] = tostring(reason or (loaded and "no lookup tables" or "not loaded"))
			end
		end
	end
	table.sort(packs, function(a, b) return a.priority > b.priority end)
	if #packs > 0 and (IsAddOnLoaded("AI_VoiceOver_Continued") or IsAddOnLoaded("AI_VoiceOver")) then
		MelloUI:Notice("Voice Over: another voice-over addon is also enabled, so lines may play twice. Disable one of them.")
	end
	if #packs > 0 then
		TellNewPack()
	end
end

-- The pack texts keep the placeholders ($n name, $c class, $r race) that the
-- live text has already filled in. Put the placeholders back, drop case and
-- punctuation, so both sides compare on words alone.
local playerTokens = nil

local function PlayerTokens()
	if playerTokens then
		return playerTokens
	end
	playerTokens = {}
	local function Add(value, placeholder)
		if type(value) == "string" and not IsSecret(value) and value ~= "" then
			playerTokens[#playerTokens + 1] = { value:lower(), placeholder }
		end
	end
	local ok, name = pcall(UnitName, "player")
	if ok then Add(name, "$n") end
	local ok2, class = pcall(UnitClass, "player")
	if ok2 then Add(class, "$c") end
	local ok3, race = pcall(UnitRace, "player")
	if ok3 then Add(race, "$r") end
	return playerTokens
end

local function Normalise(text)
	text = text:lower()
	for _, pair in ipairs(PlayerTokens()) do
		local value, placeholder = pair[1], pair[2]
		text = text:gsub(value:gsub("%p", "%%%0"), placeholder)
	end
	-- $N / $C / $R are the capitalised forms of the same placeholders; $B is
	-- a line break in the pack texts, plain whitespace in the live text.
	-- $Gmale:female; is the player's sex's word: the colon form, as every
	-- quest text writes it (the old ";...;" pattern ran on to the next
	-- semicolon and ate the words between).
	text = text:gsub("%$g[^:;]*:[^;]*;", " ")
	text = text:gsub("%$b", " ")
	text = text:gsub("[^%w%$%s]", " ")
	return text
end

-- Word overlap between two texts, 0..1 (the matcher the VoiceOver addon uses).
local function Similarity(a, b)
	local tokensA, tokensB = {}, {}
	for token in Normalise(a):gmatch("%S+") do tokensA[token] = true end
	for token in Normalise(b):gmatch("%S+") do tokensB[token] = true end
	local intersection, union = 0, 0
	for token in pairs(tokensA) do
		union = union + 1
		if tokensB[token] then intersection = intersection + 1 end
	end
	for token in pairs(tokensB) do
		if not tokensA[token] then union = union + 1 end
	end
	if union == 0 then return 0 end
	return intersection / union
end

local function BestMatch(query, entries, minimum)
	local exact = entries[query]
	if exact ~= nil then
		return exact, 1
	end
	local bestValue, bestScore = nil, minimum or 0
	for text, value in pairs(entries) do
		local score = Similarity(query, text)
		if score > bestScore then
			bestValue, bestScore = value, score
		end
	end
	return bestValue, bestScore
end

local function PackFile(pack, kind, fileName)
	local lengths = pack.data.SoundLengthLookupByFileName
	local folder = kind == "gossip" and "gossip" or "quests"
	-- Lines whose words depend on the player's gender ($G) exist only as
	-- m- / f- files (213 quest lines of the vanilla pack have no plain file):
	-- the player's own gender first, the plain file, then either gendered
	-- file rather than silence when UnitSex answers nothing on this client.
	local sex = PlainNumber(select(2, pcall(UnitSex, "player")))
	local prefix = sex == 2 and "m-" or (sex == 3 and "f-" or nil)
	if prefix and lengths[prefix .. fileName] then
		fileName = prefix .. fileName
	elseif not lengths[fileName] then
		if lengths["m-" .. fileName] then
			fileName = "m-" .. fileName
		elseif lengths["f-" .. fileName] then
			fileName = "f-" .. fileName
		else
			return nil
		end
	end
	return string.format("Interface\\AddOns\\%s\\generated\\sounds\\%s\\%s.mp3", pack.name, folder, fileName), lengths[fileName], fileName
end

local function FirstWords(text, n)
	local words = {}
	for word in text:gmatch("%S+") do
		words[#words + 1] = word
		if #words >= n then break end
	end
	return table.concat(words, " ")
end

local function LastWords(text, n)
	local words = {}
	for word in text:gmatch("%S+") do
		words[#words + 1] = word
	end
	return table.concat(words, " ", math.max(1, #words - n + 1), #words)
end

local function Unquote(text)
	return (text:gsub('"', "'"))
end

-- Quest ID from the client, or from the packs' title / NPC / text tables
-- when the client reports none.
local function ResolveQuestID(kind, npc, title, text, tablesOnly)
	if GetQuestID and not tablesOnly then
		local ok, id = pcall(GetQuestID)
		id = ok and PlainNumber(id) or nil
		if id and id > 0 then
			return id
		end
	end
	if type(title) ~= "string" or type(text) ~= "string" or IsSecret(text) then
		return nil
	end
	local cleanTitle = Unquote(title)
	local cleanName = Unquote(npc and npc.name or "")
	local cleanText = Unquote(FirstWords(text, 15)) .. " " .. Unquote(LastWords(text, 15))
	for _, pack in ipairs(packs) do
		local lookup = pack.data.QuestIDLookup and pack.data.QuestIDLookup[kind]
		local byTitle = lookup and lookup[cleanTitle]
		if type(byTitle) == "number" then
			return byTitle
		elseif type(byTitle) == "table" then
			local byNPC = byTitle[cleanName]
			if type(byNPC) == "number" then
				return byNPC
			elseif type(byNPC) == "table" then
				local id = BestMatch(cleanText, byNPC, 0.3)
				if id then return id end
			end
		end
	end
	return nil
end

-- Recorded file for a quest line: path, length in seconds.
local function PackQuestLine(kind, npc, title, text, questID)
	questID = questID or ResolveQuestID(kind, npc, title, text)
	if not questID then
		Trace("%s %q: no quest ID from the client or the pack tables", kind, tostring(title))
		return nil
	end
	for _, pack in ipairs(packs) do
		local path, length, name = PackFile(pack, kind, questID .. "-" .. kind)
		if path then
			Trace("%s %q: quest %d, recorded", kind, tostring(title), questID)
			return path, length, name
		end
	end
	-- Forever gave some vanilla quests new IDs (Chief Engineer Scooty 2842 ->
	-- 80133, the Zandalar enchant quests, ...) with the old words: look the
	-- title / NPC / text up in the pack tables and take the old recording
	-- when that names a different quest with a file. A Forever recording
	-- under the new ID (above) always wins.
	local old = ResolveQuestID(kind, npc, title, text, true)
	if old and old ~= questID then
		for _, pack in ipairs(packs) do
			local path, length, name = PackFile(pack, kind, old .. "-" .. kind)
			if path then
				Trace("%s %q: quest %d has no file; recorded as quest %d (same title)", kind, tostring(title), questID, old)
				return path, length, name
			end
		end
	end
	Trace("%s %q: quest %d has no %s recording in the pack", kind, tostring(title), questID, kind)
	return nil
end

-- Recorded file for a greeting: path, length in seconds.
local function PackGossipLine(npc, text)
	if type(text) ~= "string" or IsSecret(text) or not npc then
		return nil
	end
	local who = string.format("%s (%s)", tostring(npc.name), tostring(npc.id))
	local found = false
	for _, pack in ipairs(packs) do
		local entries
		if npc.id and pack.data.GossipLookupByNPCID then
			entries = pack.data.GossipLookupByNPCID[npc.id]
		end
		if not entries and npc.name and pack.data.GossipLookupByNPCName then
			entries = pack.data.GossipLookupByNPCName[Unquote(npc.name)]
		end
		if entries then
			found = true
			local hash, score = BestMatch(text, entries, 0.4)
			if hash then
				local path, length, name = PackFile(pack, "gossip", hash)
				if path then
					Trace("greeting from %s: matched %d%%, recorded", who, math.floor(score * 100 + 0.5))
					return path, length, nil, name
				end
				Trace("greeting from %s: matched %d%% but the file is missing", who, math.floor(score * 100 + 0.5))
			else
				local _, best = BestMatch(text, entries, 0)
				local onlyHash, count = nil, 0
				for _, h in pairs(entries) do
					onlyHash = h
					count = count + 1
				end
				if M.db.preferRecordings and count == 1 then
					local path, length, name = PackFile(pack, "gossip", onlyHash)
					if path then
						Trace("greeting from %s: text differs (%d%% match) but Prefer Recordings plays the NPC's only recording", who, math.floor((best or 0) * 100 + 0.5))
						return path, length, true, name
					end
				end
				Trace("greeting from %s: best match only %d%%, below the 40%% needed", who, math.floor((best or 0) * 100 + 0.5))
			end
		end
	end
	if not found then
		Trace("greeting from %s: NPC has no recorded greetings in the pack", who)
	end
	return nil
end

local function StopFile()
	if activeHandle then
		pcall(StopSound, activeHandle)
		activeHandle = nil
	end
end

--------------------------------------------------------------------------------
-- Line collector
--
-- Records the dialog lines seen in play into the MelloUIVoiceLines saved
-- variable so Tools\export_voice_lines.py can build the list of lines that
-- need recording for a Forever sound pack. The game writes the file at
-- logout and on /reload and brings it back at login, so the store grows from
-- one session to the next; the export script still merges each file into
-- its own store, so a file that goes missing loses nothing already exported.
--------------------------------------------------------------------------------

-- clipOnly: only ever the voice pack's clip, never text-to-speech (the
-- objectives, user 2026-09-29: not their text, not their counts)
local KINDS = {
	gossip   = { label = "Greeting",       bullet = "SoundQueueBulletGossip",   quest = false },
	accept   = { label = "Quest offer",    bullet = "SoundQueueBulletAccept",   quest = true },
	progress = { label = "Quest progress", bullet = "SoundQueueBulletProgress", quest = true },
	complete = { label = "Quest turn-in",  bullet = "SoundQueueBulletComplete", quest = true },
	objectives = { label = "Objectives",   bullet = "SoundQueueBulletProgress", quest = true, clipOnly = true },
	readable = { label = "Page",           bullet = "SoundQueueBulletGossip",   quest = false, page = true },
}

local function PlainUnitValue(fn, unit)
	local ok, value = pcall(fn, unit)
	if ok and type(value) == "string" and not IsSecret(value) and value ~= "" then
		return value
	end
	return nil
end

local function Collected()
	if type(MelloUIVoiceLines) ~= "table" then
		MelloUIVoiceLines = {}
	end
	local store = MelloUIVoiceLines
	store.quests = store.quests or {}
	store.gossip = store.gossip or {}
	store.npcs = store.npcs or {}
	store.build = select(2, GetBuildInfo())
	store.player = store.player or {
		name = PlainUnitValue(UnitName, "player"),
		class = PlainUnitValue(UnitClass, "player"),
		race = PlainUnitValue(UnitRace, "player"),
	}
	return store
end

-- Put the placeholders back that the server filled in ($n name, $c class,
-- $r race), so the stored text is the same for every character and the
-- recording can say "adventurer" instead of one player's name.
local function Placeholdered(text, player)
	if type(text) ~= "string" or not player then
		return text
	end
	local function Swap(value, placeholder)
		if type(value) ~= "string" or value == "" then
			return
		end
		local pattern = "%f[%w]" .. value:gsub("%p", "%%%0") .. "%f[%W]"
		text = text:gsub(pattern, placeholder)
		local lower = value:lower()
		if lower ~= value then
			text = text:gsub("%f[%w]" .. lower:gsub("%p", "%%%0") .. "%f[%W]", placeholder)
		end
	end
	Swap(player.name, "$n")
	Swap(player.class, "$c")
	Swap(player.race, "$r")
	return text
end

local function CollectNPC(store, npc)
	if not npc or not npc.id then
		return
	end
	local rec = store.npcs[npc.id] or {}
	rec.name = npc.name or rec.name
	rec.gender = npc.gender or rec.gender
	rec.race = npc.race or rec.race
	rec.source = npc.source or rec.source
	if npc.unit then
		local ok, creatureType = pcall(UnitCreatureType, npc.unit)
		if ok and type(creatureType) == "string" and not IsSecret(creatureType) then
			rec.type = creatureType
		end
	end
	-- Where we are standing while talking is, near enough, where the NPC is:
	-- the quest list uses it as the pick-up location for NPCs no database knows.
	if not npc.remote and C_Map and C_Map.GetBestMapForUnit and C_Map.GetPlayerMapPosition then
		local okMap, mapID = pcall(C_Map.GetBestMapForUnit, "player")
		if okMap and IsPlainNumber(mapID) then
			local okPos, pos = pcall(C_Map.GetPlayerMapPosition, mapID, "player")
			if okPos and pos then
				local okXY, x, y = pcall(pos.GetXY, pos)
				if okXY and IsPlainNumber(x) and IsPlainNumber(y) then
					local okInfo, info = pcall(C_Map.GetMapInfo, mapID)
					rec.map = mapID
					rec.mapName = okInfo and info and not IsSecret(info.name) and info.name or rec.mapName
					rec.x = math.floor(x * 1000 + 0.5) / 10
					rec.y = math.floor(y * 1000 + 0.5) / 10
				end
			end
		end
	end
	store.npcs[npc.id] = rec
end

local unsavedLines = 0

local function CollectLine(entry, questID)
	if not M.db.collectLines or entry.secret or type(entry.text) ~= "string" then
		return
	end
	local store = Collected()
	local npc = entry.npc
	CollectNPC(store, npc)
	local info = KINDS[entry.kind] or KINDS.gossip
	local text = Placeholdered(entry.text, store.player)
	-- With MelloUI_VoicePack in, only its lines play (their file "v2:<key>"):
	-- the old pack never serves a line it lacks.
	local served = entry.file ~= nil and not entry.mismatch
	local rec = {
		text = text,
		npc = npc and npc.name or nil,
		npcID = npc and npc.id or nil,
		-- A recording with the right words played, from any pack. (The merged
		-- MelloUI_VoiceOverData pack carries the vanilla lines too, so the old
		-- "not our own pack" rule marked every recorded line as missing and
		-- nagged about new lines that had a recording.) "file" is the
		-- recording's name, so Tools/export_voice_lines.py can tell a line
		-- served by another quest's file (a renumbered quest) from a new one.
		recorded = served,
		file = served and entry.fileName or nil,
		seen = date("%Y-%m-%d"),
	}
	local isNew
	if info.quest then
		local key = questID and tostring(questID) or ("title:" .. tostring(entry.title))
		store.quests[key] = store.quests[key] or {}
		rec.title = entry.title
		isNew = store.quests[key][entry.kind] == nil
		store.quests[key][entry.kind] = rec
	else
		local id = npc and npc.id or 0
		store.gossip[id] = store.gossip[id] or {}
		isNew = store.gossip[id][text] == nil
		store.gossip[id][text] = rec
	end
	-- The game writes the lines at logout and on /reload; now and then a nudge says a /reload saves them sooner.
	if isNew and not rec.recorded then
		unsavedLines = unsavedLines + 1
		if unsavedLines % 5 == 0 then
			MelloUI:Notice("Voice Over: %d new lines without a recording collected (Record Dialog Lines). /reload saves them.", unsavedLines)
		end
	end
end

--------------------------------------------------------------------------------
-- The voice pack (MelloUI_VoicePack)
--
-- One voice per NPC for all of its lines. The pack's one index (index.lua,
-- written by Tools/voice_v2_pack.py) maps a key to a clip
-- (sounds\<voice>\<hash12>.ogg) and the clip's length:
--   quest lines  "<questID>-<kind>" (accept, objectives, progress,
--                complete); "m-" / "f-" in front for a line whose words
--                depend on the player's sex; "<questID>-<kind>-<npcID>" only
--                where a second giver or turn-in NPC has a voice of its own
--                (npcID 0: an object or an item, read by the narrator).
--   NPC texts    "g-<npcID>-<hash8>": every text an NPC's own window shows
--                (greetings, their pages, quest-giver and trainer
--                greetings), by the NPC and a hash of the text's words with
--                the player's name, class and race taken out.
--   pages        "r-<hash8>": a page of a book, letter, note, plaque or
--                sign, read by the narrator, by the same hash of its words;
--                P.readPages: an item's or object's name -> its books of
--                more than one page, each its pages' keys in reading order
--                (the whole book is read, FollowBook).
-- It replaces the old packs: while it is installed only it is read, and a
-- line it lacks is read with text-to-speech, or left silent, never taken
-- from an old pack (those are not even loaded). Without it the old packs
-- still play, and MelloUI says once per account where to get it. Only the
-- current mode's pack loads after login. The work is done on the dialog
-- events only: no table is built for it.
--------------------------------------------------------------------------------

local V2_ADDON = "MelloUI_VoicePack"
local v2Pack = nil        -- the pack's table; false: looked for once and not there (a /reload looks again)
local v2Error = nil       -- why it is not there, for /vo packs
local FUZZY_MATCH = 0.4   -- the word overlap a changed greeting still needs (as the old pack's)

-- The voice pack, loaded the first time it is asked for: counted only when
-- it is a table of the pack's format 2.
local function V2()
	if v2Pack == nil then
		v2Pack = false
		local data = _G[V2_ADDON]
		if type(data) ~= "table" then
			local LoadAddOn = AddOnAPI("LoadAddOn")
			if LoadAddOn then
				local ok, loaded, reason = pcall(LoadAddOn, V2_ADDON)
				if not ok then
					v2Error = tostring(loaded)
				elseif not loaded then
					v2Error = tostring(reason or "not loaded")
				end
			end
			data = _G[V2_ADDON]
		end
		if type(data) == "table" and data.format == 2 and type(data.lines) == "table" and type(data.file) == "table"
			and type(data.fileVoice) == "table" and type(data.voices) == "table" and type(data.npcs) == "table"
			and type(data.base) == "string" then
			v2Pack = data
		elseif type(data) == "table" then
			v2Error = "not a pack this version reads"
		end
	end
	return v2Pack or nil
end

-- Once per account (the saved flag newPackTold): an old pack was loaded, so
-- say where the voice pack that replaces it is. Asked by the old packs'
-- load (LoadSoundPacks), which the voice pack's own mode never makes.
TellNewPack = function()
	local db = M.db
	if not db or db.newPackTold or V2() then
		return
	end
	db.newPackTold = true
	MelloUI:Notice("MelloUI has a new voice pack, MelloUI_VoicePack, that replaces this one: download it from MelloUI's release page.")
end

-- "tts" (text-to-speech only), "v2" (MelloUI_VoicePack, and only it) or
-- "old" (the old packs, while MelloUI_VoicePack is not installed).
local function Mode()
	local db = M.db
	if not (db and db.soundPacks) then
		return "tts"
	end
	return V2() and "v2" or "old"
end

local MODE_LABELS = {   -- for /vo packs
	tts = "text-to-speech only (Use Voice Packs is off)",
	old = "the old voice pack's recordings (MelloUI_VoicePack replaces it: a separate download)",
	v2 = "the voice pack's recordings (MelloUI_VoicePack)",
}

-- A text's words as the pack's keys are made from them: lower case, every
-- character but a-z and 0-9 a space, single spaces, trimmed.
local function KeyCanon(s)
	s = s:lower():gsub("[^a-z0-9]", " "):gsub(" +", " ")
	return (s:gsub("^ ", ""):gsub(" $", ""))
end

-- a player value (name, class, race) taken out of a canonical text, whole
-- words only; the value is made canonical too, so it holds nothing a
-- pattern would read as magic
local function DropWords(s, value)
	if type(value) ~= "string" then
		return s
	end
	local words = KeyCanon(value)
	if words == "" then
		return s
	end
	s = s:gsub("%f[%w]" .. words .. "%f[%W]", " "):gsub(" +", " ")
	return (s:gsub("^ ", ""):gsub(" $", ""))
end

-- The forms a shown text is looked up by, in order: A with the player's
-- name, class and race taken out (the pack's texts leave them out), B with
-- only the name taken out (for a text that spells a class or race out, "an
-- undead infestation" told to an undead player). Never given a secret.
local function KeyForms(shown, player)
	local b = DropWords(KeyCanon(CleanText(shown)), player.name)
	local a = DropWords(DropWords(b, player.class), player.race)
	if a == b then
		return { a }
	end
	return { a, b }
end

-- 32-bit polynomial hash of a canonical text, as 8 hex digits. Exact in
-- doubles (h * 31 + 255 stays below 2^53); the halves are printed apart,
-- since %x on a value of 2^31 or more is clipped on Windows.
local function Hash8(s)
	local h = 0
	for i = 1, #s do
		h = (h * 31 + s:byte(i)) % 4294967296
	end
	return string.format("%04x%04x", math.floor(h / 65536), h % 65536)
end

-- word-set overlap of two canonical texts, 0..1
local function Jaccard(a, b)
	local setA, setB, both, all = {}, {}, 0, 0
	for word in a:gmatch("%S+") do setA[word] = true end
	for word in b:gmatch("%S+") do setB[word] = true end
	for word in pairs(setA) do
		all = all + 1
		if setB[word] then both = both + 1 end
	end
	for word in pairs(setB) do
		if not setA[word] then all = all + 1 end
	end
	if all == 0 then
		return 0
	end
	return both / all
end

M.voiceKeys = { Canon = KeyCanon, KeyForms = KeyForms, Hash8 = Hash8, Jaccard = Jaccard }   -- the key rules (for the tests)

local function KeyPlayer()
	return {
		name = PlainUnitValue(UnitName, "player"),
		class = PlainUnitValue(UnitClass, "player"),
		race = PlainUnitValue(UnitRace, "player"),
	}
end

-- Who speaks a dialog line: the NPC the window is for ("npc", then
-- "questnpc"), 0 for an object, an item, a player sharing a quest or no
-- unit. Never the target: an item's quest would take the target's voice.
local SPEAKER_UNITS = { "npc", "questnpc" }

local function SpeakerID()
	for _, unit in ipairs(SPEAKER_UNITS) do
		local ok, exists = pcall(UnitExists, unit)
		if ok and exists then
			return NPCIDFromUnit(unit) or 0
		end
	end
	return 0
end

-- A quest line's key: the speaker's own clip where the pack has one, else
-- the quest's (its main giver or turn-in NPC); the player's sex's version
-- first for a line whose words depend on it, either one when the client
-- does not say.
local function QuestKey(P, kind, speakerID, questID)
	local lines = P.lines
	local body = questID .. "-" .. kind
	local sex = PlainNumber(select(2, pcall(UnitSex, "player")))
	local prefix = sex == 2 and "m-" or (sex == 3 and "f-" or nil)
	for pass = 1, 2 do
		local key = pass == 1 and (body .. "-" .. speakerID) or body
		if prefix then
			if lines[prefix .. key] then
				return prefix .. key
			elseif lines[key] then
				return key
			end
		elseif lines["m-" .. key] then
			return "m-" .. key
		elseif lines[key] then
			return key
		elseif lines["f-" .. key] then
			return "f-" .. key
		end
	end
	return nil
end

-- A text's key: exact (form A, then B), else the NPC's text with the most
-- words in common (FUZZY_MATCH at least, as the old pack's greetings), else
-- -- with Prefer Recordings -- the NPC's only text. Returns key, mismatch,
-- the overlap.
local function TextKey(P, speakerID, shown)
	local forms = KeyForms(shown, KeyPlayer())
	local prefix = "g-" .. speakerID .. "-"
	for _, form in ipairs(forms) do
		local key = prefix .. Hash8(form)
		if P.lines[key] then
			return key, false, 1
		end
	end
	local list = type(P.npcTexts) == "table" and P.npcTexts[speakerID] or nil
	local texts = P.texts
	if type(list) ~= "table" or type(texts) ~= "table" then
		return nil, false, 0
	end
	local best, bestScore = nil, 0
	for _, index in ipairs(list) do
		local text = texts[index]
		if type(text) == "string" then
			local score = Jaccard(forms[1], text)
			if score > bestScore then
				best, bestScore = text, score
			end
		end
	end
	if best and bestScore >= FUZZY_MATCH then
		local key = prefix .. Hash8(best)
		if P.lines[key] then
			return key, false, bestScore
		end
	end
	if M.db.preferRecordings and #list == 1 and type(texts[list[1]]) == "string" then
		local key = prefix .. Hash8(texts[list[1]])
		if P.lines[key] then
			return key, true, bestScore
		end
	end
	return nil, false, bestScore
end

-- A readable page (a book, letter, note, plaque or sign in the item text
-- window) as it is read and keyed: the book layout's HTML tags and
-- entities out, the $-tokens the client may leave in taken out ($N $C $R,
-- $B a break, $G for the player's sex), and the brackets of a stage
-- direction dropped so its words are read in line. Never given a secret.
local PAGE_TAGS = { html = true, body = true, p = true, br = true, img = true, h1 = true, h2 = true, h3 = true }
local PAGE_ENTITIES = { amp = "&", lt = "<", gt = ">", quot = "\"", apos = "'", nbsp = " " }

local function PageText(text)
	text = text:gsub("<%s*/?%s*(%w+)([^<>]*)>", function(tag, rest)
		if PAGE_TAGS[tag:lower()] and (rest == "" or rest:find("^[%s/]")) then
			return " "
		end
	end)
	text = text:gsub("&(%a+);", PAGE_ENTITIES)
	local female = PlainNumber(select(2, pcall(UnitSex, "player"))) == 3
	text = text:gsub("%$[gG]%s*([^:;]*):([^;]*);", function(male, other)
		return female and other or male
	end)
	text = text:gsub("%$[bB]", " "):gsub("%$[nNcCrR]", " "):gsub("[<>]", " ")
	return text
end

-- A page's key "r-<hash8>": its words as the pack's texts keep them (form A,
-- then B, then with nothing taken out: a book may name the player's class
-- or race, or a hero who shares the player's name), else the page of the
-- open item or object (by its name) with the most words in common.
-- Returns key, the overlap.
local function PageKey(P, shown, name)
	local page = PageText(shown)
	local forms = KeyForms(page, KeyPlayer())
	local whole = KeyCanon(CleanText(page))
	if whole ~= forms[1] and whole ~= forms[2] then
		forms[#forms + 1] = whole
	end
	for _, form in ipairs(forms) do
		local key = "r-" .. Hash8(form)
		if P.lines[key] then
			return key, 1
		end
	end
	local list = type(P.readNames) == "table" and type(name) == "string" and not IsSecret(name)
		and P.readNames[KeyCanon(name)] or nil
	if type(list) ~= "table" or type(P.texts) ~= "table" then
		return nil, 0
	end
	local best, bestScore = nil, 0
	for _, index in ipairs(list) do
		local text = P.texts[index]
		if type(text) == "string" then
			local score = Jaccard(forms[1], text)
			if score > bestScore then
				best, bestScore = text, score
			end
		end
	end
	if best and bestScore >= FUZZY_MATCH and P.lines["r-" .. Hash8(best)] then
		return "r-" .. Hash8(best), bestScore
	end
	return nil, bestScore
end
M.voiceKeys.PageText, M.voiceKeys.PageKey = PageText, PageKey

-- The voice pack's clip for a line. Returns path, seconds, key, mismatch on
-- a hit; else nil, nil, nil, nil, known (the speaker is an NPC the pack
-- gives a voice, for the trace). The quest ID used comes last (the pack's
-- title table finds one the client did not give). page: a page's key and
-- overlap when already looked up (ReadPage's PageKey), else nil.
local function V2Line(kind, speakerID, questID, title, text, label, page)
	local P = v2Pack
	local key, mismatch, score
	local info = KINDS[kind] or KINDS.gossip
	if info.quest then
		if not questID and type(title) == "string" and not IsSecret(title) and type(P.titles) == "table" then
			questID = PlainNumber(P.titles[KeyCanon(title)])
		end
		if questID then
			key = QuestKey(P, kind, speakerID, questID)
		end
	elseif info.page then
		if page then
			key, score = page.key, page.score
		elseif type(text) == "string" and not IsSecret(text) then
			key, score = PageKey(P, text, title)   -- title: the item's or object's name
		end
	elseif type(text) == "string" and not IsSecret(text) then
		key, mismatch, score = TextKey(P, speakerID, text)
	end
	local voice = speakerID ~= 0 and P.npcs[speakerID] or nil
	if key then
		local file = P.lines[key]
		local fileVoice = P.fileVoice[file]
		local folder, name = P.voices[fileVoice or 0], P.file[file]
		if speakerID ~= 0 and fileVoice ~= voice then
			-- a speaker the pack gave another voice, or none (a giver it did
			-- not know): one NPC never speaks in two voices
			Trace("%s: voice pack %s, voice differs from NPC %d's: not played", label, key, speakerID)
		elseif type(folder) == "string" and type(name) == "string" then
			local how = ""
			if mismatch then
				how = string.format(" (the words differ, %d%% match; Prefer Recordings)", math.floor((score or 0) * 100 + 0.5))
			elseif score and score < 1 then
				how = string.format(" (matched %d%%)", math.floor(score * 100 + 0.5))
			end
			Trace("%s: voice pack hit %s%s", label, key, how)
			local seconds = P.seconds and PlainNumber(P.seconds[file]) or nil
			return P.base .. folder .. "\\" .. name .. ".ogg", seconds, key, mismatch, true, questID
		end
	elseif info.quest and not questID then
		Trace("%s: no quest ID for the voice pack", label)
	elseif score and score > 0 then
		Trace("%s: voice pack, best match only %d%%", label, math.floor(score * 100 + 0.5))
	end
	return nil, nil, nil, nil, voice ~= nil, questID
end

--------------------------------------------------------------------------------
-- Speech queue
--
-- Lines are queued and read one after another, like the VoiceOver addon:
-- a greeting is not cut off by the quest that follows it. The queue advances
-- on the client's playback finished event, with an estimated duration as a
-- fallback in case the event never arrives.
--------------------------------------------------------------------------------

local queue = {}          -- waiting entries
local current = nil       -- entry being spoken
local paused = false
local pausedAt = nil      -- the GetTime the line was paused at (the widget's ring holds there)
local entryCounter = 0
local finishTimer = nil
local failedWarned = false
local Widget              -- forward declaration: the widget, defined below
-- The book being read aloud (Read Books And Letters Aloud, with the voice
-- pack): { pages = its pages' keys in reading order (a book of P.readPages),
-- at = the page queued last, name = the item's or object's name }, or nil.
-- Its pages are entries with .book set; the next one is queued when one
-- ends (NextPage). Set by FollowBook; gone with Stop, a page shown by hand,
-- another book, its last page, or a new line while Queue Lines is off.
local book = nil
local NextPage            -- forward declaration, defined below

local function TexturePath(name)
	return "Interface\\AddOns\\" .. ADDON_NAME .. "\\Media\\Textures\\VoiceOver\\" .. name   -- look-ok: the book's and the bullets' pictures (content, not the window)
end

local function CancelFinishTimer()
	if finishTimer then
		finishTimer:Cancel()
		finishTimer = nil
	end
end

local function StopEngine()
	StopFile()
	if HasTTS() and C_VoiceChat.StopSpeakingText then
		pcall(C_VoiceChat.StopSpeakingText)
	end
end

-- Rough reading time so the queue still moves if no finished event comes.
local function EstimateSeconds(text, rate)
	local words = 12
	if type(text) == "string" and not IsSecret(text) then
		words = select(2, text:gsub("%S+", ""))
	end
	local perSecond = 2.3 * (1 + (rate or 0) * 0.06)
	return math.max(3, words / perSecond + 3)
end

-- Send one entry to the speech engine, or play its recorded file. Returns
-- true if it started.
local function SpeakEntry(entry)
	if entry.file then
		StopEngine()
		local ok, willPlay, handle = pcall(PlaySoundFile, entry.file, M.db.soundChannel or "Master")
		if ok and willPlay then
			activeHandle = handle
			return true
		end
		-- File missing or channel muted: fall back to speech, unless only
		-- recordings are wanted (Read Unvoiced Lines off)
		entry.file = nil
		entry.length = nil
		if entry.recordedOnly then
			return false
		end
	end
	local npc = entry.npc
	local race = npc and npc.race or nil
	local female = npc and npc.female or false
	local voiceID = PickVoice(race, female)
	if voiceID == nil then
		if not failedWarned then
			failedWarned = true
			MelloUI:Print("Voice Over: no text-to-speech voices installed. Add voices in Windows speech settings.")
		end
		return false
	end
	StopEngine()
	local volume = tonumber(M.db.volume) or 100
	local ok = pcall(C_VoiceChat.SpeakText, voiceID, entry.text, SpeechRate(), volume, false)
	return ok
end

local PlayNext

local function OnFinished(entry)
	if entry ~= current then
		return
	end
	CancelFinishTimer()
	current = nil
	NextPage(entry.book)   -- a book's page read: its next page
	if not paused then
		PlayNext()
	end
	Widget:Update()
end

local function StartEntry(entry)
	current = entry
	entry.startedAt = GetTime()
	CancelFinishTimer()
	if not SpeakEntry(entry) then
		current = nil
		return false
	end
	local seconds
	if entry.file and entry.length then
		seconds = entry.length + 0.5
	else
		seconds = EstimateSeconds(entry.text, SpeechRate())
	end
	entry.expected = seconds
	finishTimer = C_Timer.NewTimer(seconds, function()
		finishTimer = nil
		OnFinished(entry)
	end)
	return true
end

PlayNext = function()
	while not current and #queue > 0 do
		local entry = table.remove(queue, 1)
		if StartEntry(entry) then
			break
		end
		NextPage(entry.book)   -- (a book's page that would not play: the book goes on)
	end
end

-- The next page of the book whose page ended (read, skipped, or its clip
-- would not play), queued behind what was queued meanwhile: a quest line
-- opened while the page was read comes first, then the book goes on. The
-- narrator's clip only (the pack has no words to read aloud for a page the
-- window does not show); a page with no words or no clip is passed over, and
-- the last page ends the book. The caller plays the queue.
NextPage = function(b)
	if not b or b ~= book then
		return
	end
	book = nil
	local P = v2Pack
	if not (M.isEnabled and M.db.readBooks and P) or Mode() ~= "v2" then
		return
	end
	local female = PlainNumber(select(2, pcall(UnitSex, "player"))) == 3
	for at = b.at + 1, #b.pages do
		local slot = b.pages[at]
		local key = type(slot) == "table" and (female and slot[2] or slot[1]) or slot
		local file = type(key) == "string" and P.lines[key] or nil
		local folder = file and P.voices[P.fileVoice[file] or 0]
		local name = file and P.file[file]
		if type(folder) == "string" and type(name) == "string" then
			b.at, book = at, b
			entryCounter = entryCounter + 1
			queue[#queue + 1] = {
				id = entryCounter,
				kind = "readable",
				secret = false,
				title = string.format("Page %d of %d", at, #b.pages),
				pageNo = at,
				name = b.name,
				file = P.base .. folder .. "\\" .. name .. ".ogg",
				length = P.seconds and PlainNumber(P.seconds[file]) or nil,
				fileName = "v2:" .. key,
				recordedOnly = true,
				book = b,
			}
			Trace("page %d of %q: voice pack hit %s", at, b.name, key)
			return
		end
	end
end

local function IsPlaying()
	return current ~= nil and not paused
end

local function Stop()
	CancelFinishTimer()
	wipe(queue)
	current = nil
	book = nil
	StopEngine()
	Widget:Update()
end

-- The line being read: the next one (a book's page: its next page). A
-- waiting line: out of the queue (a book's page: the book ends there).
local function Skip(entry)
	if entry == current then
		CancelFinishTimer()
		current = nil
		StopEngine()
		NextPage(entry.book)
		if not paused then
			PlayNext()
		end
	else
		for i, queued in ipairs(queue) do
			if queued == entry then
				table.remove(queue, i)
				if entry.book and entry.book == book then
					book = nil
				end
				break
			end
		end
	end
	Widget:Update()
end

local function SetPaused(state)
	if paused == state then
		return
	end
	paused = state
	pausedAt = paused and GetTime() or nil
	if paused then
		CancelFinishTimer()
		StopEngine()
	else
		if current then
			-- Text-to-speech cannot resume mid sentence; the line restarts.
			StartEntry(current)
		else
			PlayNext()
		end
	end
	Widget:Update()
end

local function TogglePaused()
	SetPaused(not paused)
end

-- Queue a line. npc is a table from DescribeNPC (or nil), kind a KINDS key.
-- matchText, when given, is the text the pack lookups compare (a quest
-- panel's text as the window gave it). opts (or nil):
--   speaker    the NPC ID the voice pack looks the line up for (the quest
--              log's giver), else the dialog's NPC (SpeakerID)
--   follow     the line goes on after the one queued just before it (the
--              objectives after the offer): never cuts it off
--   page       a page's voice pack key and overlap, already looked up
--              ({ key =, score = }: ReadPage)
-- A clipOnly kind (the objectives) is queued only when the voice pack has
-- its clip, and a clip of it that fails to play stays silent: it is never
-- read with text-to-speech. Returns the entry when it was queued.
local function Enqueue(text, npc, kind, title, questID, matchText, opts)
	if not HasTTS() then
		return
	end
	local info = KINDS[kind] or KINDS.gossip
	if info.clipOnly and Mode() ~= "v2" then
		return   -- only the voice pack has such a line
	end
	text = CleanText(text)
	if text == nil then
		return
	end
	local secret = IsSecret(text)
	if not secret then
		if text == "" then
			return
		end
		-- The same window can fire its event twice (e.g. QUEST_DETAIL on
		-- refresh); do not queue identical text again.
		if current and current.text == text then
			return
		end
		for _, entry in ipairs(queue) do
			if entry.text == text then
				return
			end
		end
	end
	if M.db.queueLines then
		-- A greeting never waits behind a quest line (the player has already
		-- moved on to the quest); a page the player opened does.
		if not info.quest and not info.page then
			if current and KINDS[current.kind].quest then
				return
			end
			for _, entry in ipairs(queue) do
				if KINDS[entry.kind].quest then
					return
				end
			end
		end
	elseif not (opts and opts.follow) then
		CancelFinishTimer()
		wipe(queue)
		current = nil
		book = nil   -- (a book being read is cut off with its page)
	end
	local mode = Mode()
	local speakerID
	if mode == "v2" then
		speakerID = opts and opts.speaker or SpeakerID()
		if speakerID == 0 and npc and npc.unit == "target" then
			npc = nil   -- an object's or an item's line: never the target's voice or face
		end
	end
	entryCounter = entryCounter + 1
	local entry = {
		id = entryCounter,
		text = text,
		secret = secret,
		npc = npc,
		kind = kind,
		title = title or info.label,
		name = npc and npc.name or (info.page and (title or info.label)) or nil,   -- a page: the book's name on the plate
	}
	matchText = matchText or text
	-- The old packs only in their own mode (MelloUI_VoicePack not
	-- installed), loaded then. With it, a line it lacks is read with
	-- text-to-speech or left silent, never the old pack's. (A page, or a
	-- quest's objectives, is only ever in the voice pack.)
	local oldPack = mode == "old" and not info.page
	if mode == "v2" then
		local label = info.quest and string.format("%s %q", kind, tostring(title))
			or info.page and string.format("page of %q", tostring(title))
			or string.format("greeting from %s (%d)", tostring(npc and npc.name), speakerID)
		local path, seconds, key, mismatch, known, foundID = V2Line(kind, speakerID, questID, title, matchText, label,
			info.page and opts and opts.page or nil)
		questID = questID or foundID
		if path then
			entry.file, entry.length, entry.mismatch = path, seconds, mismatch or nil
			entry.fileName = "v2:" .. key
		else
			local how = info.clipOnly and "not read"
				or M.db.speakUnrecorded == false and "silent" or "text-to-speech"
			if known then
				Trace("%s: NPC %d speaks in the voice pack, which has no such line: %s", label, speakerID, how)
			else
				Trace("%s: %s not in the voice pack: %s", label,
					info.page and "the page" or (speakerID ~= 0 and ("NPC " .. speakerID) or "object or item"), how)
			end
			if info.clipOnly then
				return nil
			end
		end
	end
	if oldPack then
		-- The pack tables also resolve quest IDs the client does not give.
		LoadSoundPacks()
	end
	if info.quest and not questID then
		questID = ResolveQuestID(kind, npc, title, matchText)
	end
	entry.questID = questID
	if oldPack and #packs > 0 then
		local path, length, mismatch, fileName
		if info.quest then
			path, length, fileName = PackQuestLine(kind, npc, title, matchText, questID)
		else
			path, length, mismatch, fileName = PackGossipLine(npc, text)
		end
		entry.file = path
		entry.length = length
		entry.mismatch = mismatch or nil
		entry.fileName = fileName
	end
	if not info.clipOnly and not info.page then   -- the recorder keeps NPC and quest lines only
		CollectLine(entry, questID)
	end
	-- Read Unvoiced Lines off (user, 2026-09-26: "turn off TTS Voices if the
	-- Dialog is not voiced"): with the packs on, a line with no recording is
	-- left silent.
	if not entry.file and M.db.soundPacks and M.db.speakUnrecorded == false then
		if not M.db.queueLines and not (opts and opts.follow) then
			StopEngine()   -- a new window still ends the line before it, as it does when that line is read
		end
		Widget:Update()
		return
	end
	if entry.file and (info.clipOnly or (M.db.soundPacks and M.db.speakUnrecorded == false)) then
		entry.recordedOnly = true   -- a file that fails to play stays silent too
	end
	queue[#queue + 1] = entry
	if not current and not paused then
		PlayNext()
	end
	Widget:Update()
	return entry
end

-- Speak a line straight away outside the queue (settings samples).
local function SpeakSample(text, npc)
	if not HasTTS() then
		return
	end
	CancelFinishTimer()
	current = nil
	SpeakEntry({ text = text, secret = false, npc = npc })
	Widget:Update()
end

--------------------------------------------------------------------------------
-- The widget (0.16.0; the user, 2026-09-29: the old 600 x 200 window was a
-- "HUGE dialog window": now one row of MelloUI's widget column,
-- Core/Reminders.lua "The column", in the picked look -- A's layout with C's
-- ring, docs/plans/next-update-refs/voiceover_widget_picked.jpg)
--
-- The speaker's 3D face in the round kit rim, talking while the line plays
-- (the Book for a page or an object, and with 3D Portrait off); their name
-- and the line (its kind's bullet and title) on the soft band, the
-- subtitles under them (Subtitles: in pages, as the voice goes on); a gold
-- ring round the face that fills as the line plays -- a voice pack line
-- exactly (its clip's length), a text-to-speech line by the estimate (its
-- time with a "~"), a book as the WHOLE book ("Page 2 of 5 · 1:52 left");
-- the lines waiting on its count. Paused: the ring stops, muted, and the
-- face dims under a pause glyph (a resume starts the line again, the ring
-- too). Its buttons, on hover: Pause / Resume (a click on the face too), Skip
-- to the next line or Stop when nothing waits (it ends a book too), Lines (the
-- tray: each line's length and "3 lines: 0:39 left in all"; a click skips the
-- one playing or takes a waiting one out) and the padlock (Lock The Widgets,
-- the column's Edit Layout plate). A right click stops. Shown in combat too.
--------------------------------------------------------------------------------

local WIDGET = "voiceover"   -- its key in the column
Widget = {}
local W_TEXT = {
	label = "Voice Over",
	unknown = "Unknown",
	pause = "Pause", pauseDesc = "Hold the line here.",
	resume = "Resume", resumeDesc = "The line starts again from the top.",
	skip = "Skip", skipDesc = "Go on to the next line.",
	stop = "Stop", stopDesc = "Stop reading (a book too).",
	lines = "Lines", linesDesc = "The line being read and the lines waiting, each with its length.",
	locked = "Unlock", lockedDesc = "The widgets are locked in place. Click to unlock: then drag any widget to move them.",
	unlocked = "Lock", unlockedDesc = "Drag any widget to move them (or use Edit Layout). Click to lock them in place.",
	hint = "Click: pause or resume. Right-click: stop.",
	left = "%s left",
	estimate = "~%s left",
	page = "%s left in the book",
	oneLine = "1 line: %s left",
	lines_ = "%d lines: %s left in all",
}

local function Head()
	return current or queue[1]
end

-- the player's gender picks a page's narrator (female: the second key)
local function PlayerFemale()
	return PlainNumber(select(2, pcall(UnitSex, "player"))) == 3
end

-- a book's pages' lengths (the voice pack's P.seconds), once per book
local function BookTimes(b)
	local lengths = b.lengths
	if lengths then
		return lengths
	end
	local P = v2Pack
	local female = PlayerFemale()
	lengths = { total = 0 }
	for i = 1, #b.pages do
		local slot = b.pages[i]
		local key = type(slot) == "table" and (female and slot[2] or slot[1]) or slot
		local file = P and type(key) == "string" and P.lines[key] or nil
		local secs = file and P.seconds and PlainNumber(P.seconds[file]) or 0
		lengths[i] = secs
		lengths.total = lengths.total + secs
	end
	b.lengths = lengths
	return lengths
end

-- a line's length in seconds: the clip's, else the estimate it was timed by
-- (a line still waiting: estimated now)
local function LineSeconds(e)
	if e.file and e.length then
		return e.length
	end
	if e.expected then
		return e.expected
	end
	if e.secret or type(e.text) ~= "string" then
		return nil
	end
	return EstimateSeconds(e.text, SpeechRate())
end

-- the seconds left of the line being read
local function LeftOf(e)
	local length = LineSeconds(e)
	if not (length and e.startedAt) then
		return length
	end
	local at = pausedAt or GetTime()
	local left = length - (at - e.startedAt)
	return left > 0 and left or 0
end

-- the ring: start, duration[, pausedAt]
local function Progress()
	local e = current
	if not (e and e.startedAt) then
		return nil
	end
	local b = e.book
	if b and e.pageNo then
		local L = BookTimes(b)
		if L.total > 0 then
			local before = 0
			for i = 1, e.pageNo - 1 do
				before = before + (L[i] or 0)
			end
			return e.startedAt - before, L.total, pausedAt
		end
	end
	local length = LineSeconds(e)
	if not (length and length > 0) then
		return nil
	end
	return e.startedAt, length, pausedAt
end

local function TimeText(_, left, isPaused)
	if not left then
		return nil
	end
	if isPaused then
		return MelloUI.Reminders.TEXT.paused
	end
	-- (rounded up: a line still playing never reads "0:00 left", user 2026-09-30)
	left = math.ceil(left)
	local Clock = MelloUI.Reminders.Clock
	local e = current
	if e and e.book and e.pageNo then
		-- (the page is on the line above: the time is the whole book's)
		return W_TEXT.page:format(Clock(left))
	end
	if e and not e.file then
		return W_TEXT.estimate:format(Clock(left))
	end
	return W_TEXT.left:format(Clock(left))
end

-- Split a line into pages that fit the subtitle's lines, sentence by
-- sentence (a single too-long sentence is split on words). fits(text) ->
-- true when a page shows whole.
local function BuildPages(fits, text)
	local function Pack(pieces)
		local pages, page = {}, ""
		for _, piece in ipairs(pieces) do
			local candidate = page == "" and piece or (page .. " " .. piece)
			if page ~= "" and not fits(candidate) then
				pages[#pages + 1] = page
				page = piece
			else
				page = candidate
			end
		end
		if page ~= "" then
			pages[#pages + 1] = page
		end
		return pages
	end
	local sentences = {}
	for raw in text:gmatch("%s*([^%.!%?]+[%.!%?]*)") do
		local sentence = raw:gsub("^%s+", ""):gsub("%s+$", "")
		if sentence ~= "" then
			sentences[#sentences + 1] = sentence
		end
	end
	local pages = {}
	for _, page in ipairs(Pack(sentences)) do
		if fits(page) then
			pages[#pages + 1] = page
		else
			local words = {}
			for word in page:gmatch("%S+") do
				words[#words + 1] = word
			end
			for _, part in ipairs(Pack(words)) do
				pages[#pages + 1] = part
			end
		end
	end
	return #pages > 0 and pages or { text }
end

-- How long a page takes to SAY, in letters: its own letters plus the pauses
-- the voice makes at its punctuation -- about half a second at a full stop,
-- a quarter at a comma, which at a speaking pace of some 14 letters a second
-- are 7 and 3 letters (user, 2026-09-23: "go ahead with the subtitle
-- pacing"). A page ending a sentence carries that sentence's pause, so the
-- next page comes up when the voice starts it again, not during the pause.
local STOP_PAUSE, COMMA_PAUSE = 7, 3

local function SpokenWeight(text)
	local _, stops = text:gsub("[%.!%?]+", "")
	local _, commas = text:gsub("[,;:]", "")
	return #text + stops * STOP_PAUSE + commas * COMMA_PAUSE
end

-- Which page the playback is on: the share of the clip played so far against
-- the pages' spoken weights. The clip's own length where it is known (a
-- recorded line), else the estimate the text-to-speech line was timed by.
local function SubtitlePage(entry)
	local pages = entry.pages
	if not pages or #pages <= 1 then
		return 1
	end
	if not entry.pageWeights then
		local weights, total = {}, 0
		for i, page in ipairs(pages) do
			weights[i] = SpokenWeight(page)
			total = total + weights[i]
		end
		entry.pageWeights, entry.pageTotal = weights, total
	end
	local length = entry.length or entry.expected
	local progress = 0
	if length and length > 0 and entry.startedAt and not paused then
		progress = (GetTime() - entry.startedAt) / length
	end
	local at, index = 0, 1
	for i, weight in ipairs(entry.pageWeights) do
		if progress >= at / entry.pageTotal then
			index = i
		end
		at = at + weight
	end
	return math.min(index, #pages)
end
Widget.SubtitlePage = SubtitlePage

local function SubFits(text)
	return MelloUI.Reminders:SubFits(text)
end

-- the subtitle: the page being said of the line being read (a book's page
-- the window does not show, or a secret line: none)
local function Subtitle()
	local e = current
	if not (M.db.overlaySubtitles and e and not e.secret and type(e.text) == "string" and e.text ~= "") then
		return nil
	end
	if not e.pages then
		e.pages = BuildPages(SubFits, e.text)
		e.pageWeights = nil
	end
	e.page = SubtitlePage(e)
	return e.pages[e.page] or e.text
end

local function HasNext()
	if #queue > 0 then
		return true
	end
	local e = current
	return e ~= nil and e.book ~= nil and e.book == book and e.pageNo ~= nil and e.pageNo < #e.book.pages
end

local function WidgetsLocked()
	local db = MelloUI:GetModuleDB("Reminders")
	return db ~= nil and db.widgetLock == true
end

local function ToggleLock()
	local on = not WidgetsLocked()
	MelloUI:NotifySettingChanged("Reminders", "widgetLock", on)
	MelloUI:PlayUISound(on and "option_on" or "option_off")
	Widget:Update()
end

-- the tray: the line being read, then the lines waiting
local function TrayRowClick(_, row)
	if row.line then
		Skip(row.line)
	end
end

local function Tray(_, rows)
	local Clock = MelloUI.Reminders.Clock
	local n, total, known = 0, 0, true
	local function Add(e, isCurrent)
		n = n + 1
		local r = rows[n] or {}
		rows[n] = r
		local secs = isCurrent and LeftOf(e) or LineSeconds(e)
		r.line = e
		r.icon = nil
		r.glyph = isCurrent and (paused and "pause" or "play") or "cross"
		r.text = e.title or (KINDS[e.kind] or KINDS.gossip).label
		if secs then
			total = total + secs
			r.right = isCurrent and W_TEXT.left:format(Clock(secs)) or Clock(secs)
		else
			known = false
			r.right = ""
		end
		r.onClick = TrayRowClick
	end
	if current then
		Add(current, true)
	end
	for _, e in ipairs(queue) do
		Add(e, false)
	end
	rows.n = n
	if n == 0 or not known then
		return nil
	end
	if n == 1 then
		return W_TEXT.oneLine:format(Clock(total))
	end
	return W_TEXT.lines_:format(n, Clock(total))
end

local SPEC = {
	key = WIDGET, column = true, label = W_TEXT.label, hint = W_TEXT.hint, rightClick = true,
	-- (the column's bottom slot: no other widget moves what is being read;
	-- a fight neither stops nor hides it, Compact In Combat only shrinks it)
	bottom = true,
	compact = function()
		return M.db.overlayCompact ~= false
	end,
	enabled = function()
		return M.isEnabled and M.db.overlay and true or false
	end,
	check = function()
		return current ~= nil or #queue > 0
	end,
	title = function()
		local h = Head()
		return h and (h.name or W_TEXT.unknown) or ""
	end,
	text = function()
		local h = Head()
		if not h then
			return ""
		end
		local info = KINDS[h.kind] or KINDS.gossip
		local title = h.title or info.label
		if IsSecret(title) then
			return title
		end
		return "|T" .. TexturePath(info.bullet) .. ":14:14|t " .. tostring(title)
	end,
	icon = TexturePath("Book"),
	model = function()
		local h = Head()
		return M.db.overlayPortrait and h and h.npc and h.npc.id or nil
	end,
	talking = function()
		return IsPlaying()
	end,
	count = function()
		return #queue
	end,
	progress = Progress,
	time = TimeText,
	sub = Subtitle,
	tray = Tray,
	onClick = function(_, mouse)
		if mouse == "RightButton" then
			Stop()
		else
			TogglePaused()
		end
	end,
	actions = {
		{ glyph = function() return paused and "play" or "pause" end,
		  tip = function() return paused and W_TEXT.resume or W_TEXT.pause end,
		  desc = function() return paused and W_TEXT.resumeDesc or W_TEXT.pauseDesc end,
		  fn = function() TogglePaused() end },
		{ glyph = "skip", tip = W_TEXT.skip, desc = W_TEXT.skipDesc, shown = HasNext,
		  fn = function()
			local e = current or queue[1]
			if e then
				Skip(e)
			end
		  end },
		{ glyph = "stop", tip = W_TEXT.stop, desc = W_TEXT.stopDesc, shown = function() return not HasNext() end,
		  fn = function() Stop() end },
		{ glyph = "list", tip = W_TEXT.lines, desc = W_TEXT.linesDesc, tray = true },
		{ glyph = function() return WidgetsLocked() and "padlock" or "padlockOpen" end,
		  tip = function() return WidgetsLocked() and W_TEXT.locked or W_TEXT.unlocked end,
		  desc = function() return WidgetsLocked() and W_TEXT.lockedDesc or W_TEXT.unlockedDesc end,
		  fn = ToggleLock },
	},
}

-- the row laid again on the next frame (a new line, a pause, a skip ...)
function Widget:Update()
	if self.registered then
		MelloUI.Reminders:Refresh(WIDGET)
	end
end

function Widget:Register()
	if not self.registered then
		self.registered = true
		MelloUI.Reminders:Register(SPEC)
	end
end

function Widget:Unregister()
	if self.registered then
		self.registered = false
		MelloUI.Reminders:Unregister(WIDGET)
	end
end

-- the row showing Voice Over now, for /vo portrait (nil: none)
function Widget:Row()
	local col = MelloUI.Reminders:Column()
	for _, row in ipairs(col and col.rows or {}) do
		if row.key == WIDGET then
			return row
		end
	end
	return nil
end

--------------------------------------------------------------------------------
-- Dialog events
--------------------------------------------------------------------------------

local function PlainString(value)
	if type(value) == "string" and not IsSecret(value) then
		return value
	end
	return nil
end

local function QuestTitle()
	if GetTitleText then
		local ok, title = pcall(GetTitleText)
		if ok then
			return PlainString(title)
		end
	end
	return nil
end

local function GossipText()
	if C_GossipInfo and C_GossipInfo.GetText then
		local ok, text = pcall(C_GossipInfo.GetText)
		if ok then
			return text
		end
	end
	if GetGossipText then
		return GetGossipText()
	end
end

--------------------------------------------------------------------------------
-- Quest panels: read once the client has filled them in
--
-- QUEST_DETAIL / QUEST_PROGRESS / QUEST_COMPLETE fire synchronously, and on
-- the current Classic-line clients GetQuestID() can still answer 0, or the
-- previous quest's globals can still be in place, at that moment: the line
-- lost its recording or the wrong quest was read. The read is put off to
-- the next frame and retried a few times until the ID, title and text are
-- there, keyed so the same panel is not read twice when the event repeats.
--------------------------------------------------------------------------------

local QUEST_PANELS = { accept = "QuestFrameDetailPanel", progress = "QuestFrameProgressPanel", complete = "QuestFrameRewardPanel" }
local QUEST_TEXT = {
	accept = function() return GetQuestText and GetQuestText() or nil end,
	progress = function() return GetProgressText and GetProgressText() or nil end,
	complete = function() return GetRewardText and GetRewardText() or nil end,
}
local READ_TRIES, READ_STEP = 5, 0.1
local lastRead = { key = nil, at = 0 }
local readSerial = 0

local function ClientQuestID()
	if not GetQuestID then
		return nil
	end
	local ok, id = pcall(GetQuestID)
	id = ok and PlainNumber(id) or nil
	return id and id > 0 and id or nil
end

local function QuestPanelShown(kind)
	local panel = _G[QUEST_PANELS[kind]]
	-- No such frame on this client: trust the event.
	return not panel or panel:IsShown()
end

local function ReadQuestPanel(kind, serial, attempt)
	if serial ~= readSerial or not M.isEnabled or not QuestPanelShown(kind) then
		return
	end
	local questID = ClientQuestID()
	local title = QuestTitle()
	local text = QUEST_TEXT[kind]()
	local plain = PlainString(text)
	local ready = questID ~= nil and title ~= nil and (IsSecret(text) or (plain ~= nil and plain ~= ""))
	if not ready and attempt < READ_TRIES then
		C_Timer.After(READ_STEP, function() ReadQuestPanel(kind, serial, attempt + 1) end)
		return
	end
	local key = kind .. ":" .. tostring(questID or 0) .. ":" .. tostring(title)
	if key == lastRead.key and GetTime() - lastRead.at < 5 then
		return
	end
	lastRead.key, lastRead.at = key, GetTime()
	Trace("%s %q: client quest ID %s after %d read(s)", kind, tostring(title), tostring(questID or "none"), attempt)
	local npc = DescribeNPC()
	Enqueue(text, npc, kind, title, questID, text)
	-- after the offer, a line of its own: the voice pack's objectives clip
	-- (Quest Objectives), or nothing when it has none. Text-to-speech never
	-- reads the objectives (user, 2026-09-29: the pack has them recorded).
	if kind == "accept" and M.db.recordedObjectives and plain and GetObjectiveText and Mode() == "v2" then
		local objectives = GetObjectiveText()
		if type(objectives) == "string" and not IsSecret(objectives) and objectives ~= "" then
			Enqueue(objectives, npc, "objectives", "Objectives" .. (title and (": " .. title) or ""), questID, nil,
				{ follow = true })
		end
	end
end

local function ScheduleQuestRead(kind)
	readSerial = readSerial + 1
	local serial = readSerial
	C_Timer.After(0, function() ReadQuestPanel(kind, serial, 1) end)
end

--------------------------------------------------------------------------------
-- Books, letters, notes, plaques and signs (the item text window)
--
-- The page shown is read in the narrator's voice (the voice pack's "r-" key)
-- or with text-to-speech, and then, with the voice pack, every page after it
-- to the end of the book, one as each ends (user, 2026-09-29: "it should just
-- read the whole book"): no page turning, and closing the window (or the
-- game closing it as the player walks away) does not stop it. A page turned
-- by hand reads on from that page; another book replaces it; Stop ends it.
-- Read on ITEM_TEXT_READY, which comes for the first page and for every page
-- turn; the pages after it go on the queue as the one before ends (the clip's
-- end, as every line): nothing runs in between.
--------------------------------------------------------------------------------

local function ItemTextValue(name)
	local fn = _G[name]
	if type(fn) == "function" then
		local ok, value = pcall(fn)
		if ok then
			return value
		end
	end
	return nil
end

-- whether the window shows a next page: true or false, nil when the client
-- does not say
local function WindowHasNext()
	local fn = _G["ItemTextHasNextPage"]
	if type(fn) ~= "function" then
		return nil
	end
	local ok, value = pcall(fn)
	if not ok or IsSecret(value) then
		return nil
	end
	return value and true or false
end

-- the book being read and its pages being read or waiting, out of the queue
local function StopPages()
	book = nil
	for i = #queue, 1, -1 do
		if queue[i].kind == "readable" then
			table.remove(queue, i)
		end
	end
	if current and current.kind == "readable" then
		Skip(current)
	else
		Widget:Update()
	end
end

-- The book the shown page is in: the voice pack's books of the item's or
-- object's name (P.readPages), the one holding the page's key; where two
-- books of that name hold it, the page number the window shows and a book
-- that goes on past it (the window shows a next page) settle it. A page the
-- pack does not know (words changed, a secret text) is placed by its number
-- when the name has one book. The window's last page: nothing follows.
-- Returns the book's pages and the page's place in them, or nil.
local function FindBook(name, key)
	local P = v2Pack
	local books = P and type(name) == "string" and type(P.readPages) == "table" and P.readPages[KeyCanon(name)]
	if type(books) ~= "table" or WindowHasNext() == false then
		return nil
	end
	local number = PlainNumber(ItemTextValue("ItemTextGetPage"))
	local pages, at, best = nil, nil, -1
	if key then
		for _, list in ipairs(books) do
			for i = 1, #list do
				local slot = list[i]
				if slot == key or (type(slot) == "table" and (slot[1] == key or slot[2] == key)) then
					local score = (i == number and 2 or 0) + (i < #list and 1 or 0)
					if score > best then
						pages, at, best = list, i, score
					end
				end
			end
		end
	end
	if not pages and #books == 1 and number and books[1][number] ~= nil then
		pages, at = books[1], number
	end
	if pages and at < #pages then
		return pages, at
	end
	return nil
end

-- A readable page queued (entry; nil when it was not: no recording and Read
-- Unvoiced Lines off): its book is followed to the end. The page's line says
-- which page of how many; a page that is not read goes straight on to the
-- next.
local function FollowBook(entry, name, key)
	local pages, at = FindBook(name, key)
	if not pages then
		return
	end
	book = { pages = pages, at = at, name = name }
	local waiting = entry ~= nil and entry == current
	if entry then
		entry.book = book
		entry.title = string.format("Page %d of %d", at, #pages)
		entry.pageNo = at
		for _, queued in ipairs(queue) do
			waiting = waiting or queued == entry
		end
	end
	if not waiting then
		NextPage(book)
		if not current and not paused then
			PlayNext()
		end
	end
	Widget:Update()
end

local function ReadPage()
	local text = ItemTextValue("ItemTextGetText")
	if type(text) ~= "string" then
		return
	end
	local name = PlainString(ItemTextValue("ItemTextGetItem"))
	local found = nil   -- the page's key in the voice pack, looked up once
	if not IsSecret(text) then
		text = PageText(text)
		local shown = CleanText(text)
		if shown == "" then
			return   -- a picture page
		end
		if Mode() == "v2" then
			local key, score = PageKey(v2Pack, shown, name)
			found = { key = key, score = score }
		end
		-- (the same book's: another of a different name that shares the
		-- page's words is read instead; no name from the client: as before)
		if current and current.kind == "readable" and not current.secret
			and (name == nil or current.name == name)
			and (current.text == shown or (found and found.key and current.fileName == "v2:" .. found.key)) then
			-- the page being read shown again: it goes on, and a page the
			-- book went on to by itself (no words, only its sound) takes the
			-- window's words for its subtitles (user, 2026-09-30: turning
			-- the pages lost them)
			if current.text == nil then
				current.text = shown
				current.pages, current.pageWeights = nil, nil
				Widget:Update()
			end
			return
		end
	end
	StopPages()
	local entry = Enqueue(text, nil, "readable", name, nil, nil, { speaker = 0, page = found })
	if Mode() == "v2" then
		FollowBook(entry, name, found and found.key)
	end
end

local handlers = {
	GOSSIP_SHOW = function()
		if M.db.gossip then
			Enqueue(GossipText(), DescribeNPC(), "gossip")
		end
	end,
	QUEST_GREETING = function()
		if M.db.gossip and GetGreetingText then
			Enqueue(GetGreetingText(), DescribeNPC(), "gossip")
		end
	end,
	-- the trainer's own greeting ("Hello, priest! Ready for some training?"),
	-- a text of the NPC's own window like any other
	TRAINER_SHOW = function()
		local GetTrainerGreetingText = _G.GetTrainerGreetingText
		if M.db.gossip and GetTrainerGreetingText then
			local ok, text = pcall(GetTrainerGreetingText)
			if ok then
				Enqueue(text, DescribeNPC(), "gossip")
			end
		end
	end,
	QUEST_DETAIL = function()
		if M.db.questDetail then
			ScheduleQuestRead("accept")
		end
	end,
	QUEST_PROGRESS = function()
		if M.db.questProgress and GetProgressText then
			ScheduleQuestRead("progress")
		end
	end,
	QUEST_COMPLETE = function()
		if M.db.questComplete and GetRewardText then
			ScheduleQuestRead("complete")
		end
	end,
	GOSSIP_CLOSED = function()
		if M.db.stopOnClose then
			Stop()
		end
	end,
	QUEST_FINISHED = function()
		if M.db.stopOnClose then
			Stop()
		end
	end,
	-- (no ITEM_TEXT_CLOSED: closing the book, or walking away from it, never
	-- stops its reading)
	ITEM_TEXT_READY = function()
		if M.db.readBooks then
			ReadPage()
		end
	end,
	PLAYER_TARGET_CHANGED = function()
		if M.db.stopOnMove and current then
			Stop()
		end
	end,
	VOICE_CHAT_TTS_VOICES_UPDATE = function()
		RefreshVoices()
	end,
	VOICE_CHAT_TTS_PLAYBACK_FINISHED = function()
		if current and not current.file and not paused then
			OnFinished(current)
		end
	end,
	VOICE_CHAT_TTS_PLAYBACK_FAILED = function()
		if not failedWarned then
			failedWarned = true
			MelloUI:Print("Voice Over: text-to-speech playback failed. Check that a voice is installed and selected.")
		end
		if current and not current.file then
			OnFinished(current)
		end
	end,
}

local eventFrame = CreateFrame("Frame")
Perf.SetScript(eventFrame, "OnEvent", function(_, event, ...)
	local handler = handlers[event]
	if handler then
		handler(...)
	end
end)

--------------------------------------------------------------------------------
-- Quest log read-aloud
--
-- A button on the quest log's details view reads the selected quest: the
-- description in the giver's voice (the recorded offer line when a pack has
-- it), then the voice pack's recorded objectives line when it has one.
--------------------------------------------------------------------------------

-- The quest's row in the Quest List data (row[9] the giver's name, row[21]
-- the giver's NPC ID), found by walking the rows when a quest is read. Reading
-- is a click, not a loop, so no table of every quest is kept for it: a
-- { name, npcID } per quest held about a megabyte for a lookup made once per
-- Read. A quest listed twice takes its later row.
local function GiverRow(questID)
	local data = MelloUI_QuestListData
	if type(data) ~= "table" or type(data.quests) ~= "table" then
		return nil
	end
	local found
	for _, row in ipairs(data.quests) do
		if row[1] == questID and row[9] ~= "" then
			found = row
		end
	end
	return found
end

local function GiverForQuest(questID)
	local row = GiverRow(questID)
	if not npcLookup then
		BuildLookup()
	end
	local npcID = row and (row[21] or 0) ~= 0 and row[21] or nil
	local name = row and row[9] or nil
	if not npcID and M.db.soundPacks and Mode() == "old" then
		-- Not in the quest list data (or an item starts it): the old pack's
		-- own quest -> NPC table knows the vanilla givers. (Only in its own
		-- mode: with MelloUI_VoicePack in, the old packs are never read.)
		LoadSoundPacks()
		for _, pack in ipairs(packs) do
			local byQuest = pack.data.NPCIDLookupByQuestID
			local id = byQuest and byQuest[questID]
			if type(id) == "number" then
				npcID = id
				local names = pack.data.NPCNameLookupByNPCID
				name = name or (names and names[id]) or nil
				break
			end
		end
	end
	local info = npcID and npcLookup[npcID] or nil
	local gender = info and info.gender or "n"
	return {
		id = npcID,
		name = name,
		race = info and info.race or nil,
		gender = gender,
		female = gender == "f",
		source = info and (info.override and "override" or "data") or "unknown",
		remote = true,
	}
end

local function ReadQuest(questID)
	if not questID or not HasTTS() then
		return false
	end
	local logIndex
	if C_QuestLog and C_QuestLog.GetLogIndexForQuestID then
		local ok, idx = pcall(C_QuestLog.GetLogIndexForQuestID, questID)
		logIndex = ok and PlainNumber(idx) or nil
	end
	if not logIndex or not GetQuestLogQuestText then
		return false
	end
	local ok, description, objectivesText = pcall(GetQuestLogQuestText, logIndex)
	if not ok then
		return false
	end
	local title
	if C_QuestLog and C_QuestLog.GetTitleForQuestID then
		local okT, t = pcall(C_QuestLog.GetTitleForQuestID, questID)
		title = okT and type(t) == "string" and not IsSecret(t) and t or nil
	end
	Stop()
	local npc = GiverForQuest(questID)
	local spoken = false
	-- the voice pack's lines in the giver's voice (0: an object or an item)
	local v2 = Mode() == "v2"
	local speaker = v2 and (npc.id or 0) or nil
	if type(description) == "string" and not IsSecret(description) and description ~= "" then
		-- (Read Unvoiced Lines off and no recording: nothing queued, and
		-- the button says there is nothing to read)
		spoken = Enqueue(description, npc, "accept", title, questID, nil, v2 and { speaker = speaker } or nil) ~= nil
	end
	-- then the voice pack's objectives line (Quest Objectives), or nothing:
	-- never text-to-speech, not the counts either (user, 2026-09-29)
	local clip = nil
	if v2 and M.db.recordedObjectives and type(objectivesText) == "string" and not IsSecret(objectivesText) and objectivesText ~= "" then
		clip = Enqueue(objectivesText, npc, "objectives", "Objectives" .. (title and (": " .. title) or ""), questID, nil,
			{ speaker = speaker, follow = true })
	end
	return spoken or clip ~= nil
end

local readButton = nil

local function IsReadingLog()
	if current and current.questID and (current.kind == "accept" or current.kind == "objectives") and current.npc and current.npc.remote then
		return true
	end
	for _, entry in ipairs(queue) do
		if entry.npc and entry.npc.remote then
			return true
		end
	end
	return false
end

local function CreateReadButton()
	if readButton or not (QuestMapFrame and QuestMapFrame.DetailsFrame and QuestMapFrame.DetailsFrame.BackFrame) then
		return
	end
	local frame = QuestMapFrame.DetailsFrame.BackFrame
	readButton = CreateFrame("Button", nil, frame, "UIPanelButtonTemplate")
	readButton:SetSize(72, 22)
	readButton:SetPoint("RIGHT", frame, "RIGHT", -11, 4)
	readButton:SetText("Read")
	Perf.SetScript(readButton, "OnClick", function()
		if IsReadingLog() then
			Stop()
			MelloUI:PlayUISound("option_off")
		else
			local questID = QuestMapFrame.DetailsFrame.questID
			if not ReadQuest(questID) then
				MelloUI:Print("Voice Over: nothing to read for this quest.")
			else
				MelloUI:PlayUISound("option_on")
			end
		end
	end)
	Perf.SetScript(readButton, "OnEnter", function(self)
		MelloUI.Widgets.ShowTooltip(self, "Read aloud",
			"Reads the quest's description in the quest giver's voice, then the recorded objectives when the voice pack has them.", nil, "ANCHOR_RIGHT")
	end)
	Perf.SetScript(readButton, "OnLeave", function() GameTooltip:Hide() end)
	local acc = 0
	Perf.SetScript(readButton, "OnUpdate", function(self, elapsed)
		acc = acc + elapsed
		if acc < 0.25 then
			return
		end
		acc = 0
		local reading = IsReadingLog()
		if reading ~= self.reading then
			self.reading = reading
			self:SetText(reading and "Stop" or "Read")
		end
	end)
end

local function ApplyReadButton()
	if M.isEnabled and M.db.questLog and HasTTS() then
		CreateReadButton()
	end
	if readButton then
		readButton:SetShown(M.isEnabled and M.db.questLog and true or false)
	end
end

--------------------------------------------------------------------------------
-- Slash command
--------------------------------------------------------------------------------

local TEST_LINES = {
	"Greetings, traveller. The road ahead is long, but I trust you will manage.",
	"You there! Yes, you. I have work for someone who can swing a blade.",
	"Ah, another adventurer. Stay a while and listen.",
}

local function GenderWord(gender)
	if gender == "f" then return "female" end
	if gender == "m" then return "male" end
	return "none"
end

SLASH_MELLOVOICEOVER1 = "/voiceover"
SLASH_MELLOVOICEOVER2 = "/vo"
SlashCmdList.MELLOVOICEOVER = function(msg)
	msg = (msg or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
	if msg == "stop" or msg == "" then
		Stop()
	elseif msg == "pause" then
		TogglePaused()
		MelloUI:Print(paused and "Voice Over paused." or "Voice Over resumed.")
	elseif msg == "skip" then
		if current then
			Skip(current)
		end
	elseif msg == "read" then
		local questID = C_QuestLog and C_QuestLog.GetSelectedQuest and PlainNumber(select(2, pcall(C_QuestLog.GetSelectedQuest)))
		if not questID or questID == 0 then
			MelloUI:Print("Select a quest in the quest log first.")
		elseif not ReadQuest(questID) then
			MelloUI:Print("Nothing to read for that quest.")
		end
	elseif msg == "reset" then
		MelloUI.Reminders:ResetColumnPlace()
		MelloUI:Print("The widgets' place reset.")
	elseif msg == "lines" then
		local store = Collected()
		local quests, questLines, newQuestLines, gossip, newGossip = 0, 0, 0, 0, 0
		for _, kinds in pairs(store.quests) do
			quests = quests + 1
			for _, rec in pairs(kinds) do
				questLines = questLines + 1
				if not rec.recorded then newQuestLines = newQuestLines + 1 end
			end
		end
		for _, texts in pairs(store.gossip) do
			for _, rec in pairs(texts) do
				gossip = gossip + 1
				if not rec.recorded then newGossip = newGossip + 1 end
			end
		end
		MelloUI:Print("Collected so far: %d quest lines from %d quests (%d without a recording), %d greetings (%d without).",
			questLines, quests, newQuestLines, gossip, newGossip)
		local shown = 0
		for _, texts in pairs(store.gossip) do
			for text, rec in pairs(texts) do
				if shown < 3 then
					shown = shown + 1
					print(string.format("   %s: %s%s", tostring(rec.npc), text:sub(1, 60), rec.recorded and " (recorded)" or ""))
				end
			end
		end
		for _, kinds in pairs(store.quests) do
			for kind, rec in pairs(kinds) do
				if shown < 6 then
					shown = shown + 1
					print(string.format("   %s, %s of %q%s", tostring(rec.npc), kind, tostring(rec.title), rec.recorded and " (recorded)" or ""))
				end
			end
		end
		print("   Saved when you log out or /reload, and kept from one session to the next.")
	elseif msg == "packs" then
		local mode = Mode()
		if mode == "tts" then
			V2()   -- (Use Voice Packs off: what is installed all the same; the old packs only without it)
		end
		MelloUI:Print("Voice Over plays %s.", MODE_LABELS[mode])
		if v2Pack then
			local keys, npcs = 0, 0
			for _ in pairs(v2Pack.lines) do keys = keys + 1 end
			for _ in pairs(v2Pack.npcs) do npcs = npcs + 1 end
			MelloUI:Print("Voice pack %s: build %s, %d lines, %d recordings, %d NPCs.", V2_ADDON, tostring(v2Pack.build or "?"),
				keys, #v2Pack.file, npcs)
		elseif v2Error then
			print(string.format("   Voice pack %s: not loaded (%s).", V2_ADDON, v2Error))
		end
		if v2Pack then
			print("   Old voice packs: never read while " .. V2_ADDON .. " is installed.")
		else
			LoadSoundPacks()
			if #packs == 0 and not next(packErrors) then
				MelloUI:Print("No old voice packs installed.")
			end
			for _, pack in ipairs(packs) do
				local files = 0
				for _ in pairs(pack.data.SoundLengthLookupByFileName) do files = files + 1 end
				MelloUI:Print("Pack %s: %d recorded lines (priority %d).", pack.name, files, pack.priority)
			end
			for name, err in pairs(packErrors) do
				MelloUI:Print("Pack %s could not be loaded: %s", name, err)
			end
		end
		if current then
			print("   current line: " .. (current.file and ("recorded (" .. current.file .. ")") or "text-to-speech"))
		end
		for _, line in ipairs(lookupTrace) do
			print("   " .. line)
		end
	elseif msg == "portrait" then
		local row = Widget:Row()
		local model = row and row.model
		if not model then
			MelloUI:Print("The Voice Over widget is not showing.")
			return
		end
		local function Try(name, ...)
			local fn = model[name]
			if not fn then
				return name .. "=missing"
			end
			local ok, a, b = pcall(fn, model, ...)
			return string.format("%s=%s", name, ok and tostring(a) .. (b ~= nil and ("," .. tostring(b)) or "") or ("error: " .. tostring(a)))
		end
		MelloUI:Print("Portrait: creature %s, loaded %s, tries %s, shown %s, size %dx%d",
			tostring(model.creature), tostring(model.loaded), tostring(model.tries), tostring(model:IsShown()),
			model:GetWidth(), model:GetHeight())
		print("   " .. Try("GetModelFileID") .. "  " .. Try("GetModel") .. "  " .. Try("HasCustomCamera") .. "  " .. Try("GetModelScale"))
		print("   " .. Try("GetCameraPosition") .. "  " .. Try("GetPosition") .. "  " .. Try("GetModelAlpha"))
	elseif msg == "test" then
		if not M.isEnabled then
			MelloUI:Print("Voice Over is disabled. Enable it under /mello.")
			return
		end
		local npc = DescribeNPC(true)
		if npc then
			MelloUI:Print("Reading as %s (%s, %s).", npc.name or ("NPC " .. npc.id), npc.race or "unknown race", GenderWord(npc.gender))
		else
			MelloUI:Print("No NPC targeted; reading with the male voice.")
		end
		Enqueue(TEST_LINES[math.random(#TEST_LINES)], npc, "gossip", "Test line")
	elseif msg == "voices" then
		RefreshVoices()
		if #voices == 0 then
			MelloUI:Print("No text-to-speech voices found.")
			return
		end
		MelloUI:Print("Installed voices (male pick: %s, female pick: %s):",
			tostring(voiceByID[PickVoice(nil, false) or -1] or "none"), tostring(voiceByID[PickVoice(nil, true) or -1] or "none"))
		for _, voice in ipairs(voices) do
			print(string.format("   %d  -  %s", voice.voiceID, voice.name))
		end
	elseif msg == "npc" then
		local npc = DescribeNPC(true)
		if not npc then
			MelloUI:Print("Target or talk to an NPC first.")
			return
		end
		local voiceID = PickVoice(npc.race, npc.female)
		MelloUI:Print("%s  (NPC ID %d)", npc.name or "?", npc.id)
		print(string.format("   race: %s   gender: %s   source: %s",
			npc.race or "unknown", GenderWord(npc.gender), npc.source))
		print(string.format("   voice: %s   speed: %+d", tostring(voiceByID[voiceID or -1] or "none"), SpeechRate()))
		if npc.source == "unknown" then
			print(string.format('   Not in the data. Add to Media\\NPCVoiceOverrides.lua:  [%d] = { race = "human", gender = "%s" },',
				npc.id, npc.female and "f" or "m"))
		end
	else
		MelloUI:Print("/vo stop | pause | skip | read | test | voices | npc | packs | lines | reset | portrait")
	end
end

--------------------------------------------------------------------------------
-- Module lifecycle
--------------------------------------------------------------------------------

local EVENTS = {
	"GOSSIP_SHOW", "GOSSIP_CLOSED",
	"QUEST_GREETING", "QUEST_DETAIL", "QUEST_PROGRESS", "QUEST_COMPLETE", "QUEST_FINISHED",
	"TRAINER_SHOW",
	"ITEM_TEXT_READY",
	"PLAYER_TARGET_CHANGED",
	"VOICE_CHAT_TTS_VOICES_UPDATE", "VOICE_CHAT_TTS_PLAYBACK_FINISHED", "VOICE_CHAT_TTS_PLAYBACK_FAILED",
}

function M:OnInit(db)
	self.db = db
	-- 0.16.0: the old window's padlock is the widget column's lock (Lock The
	-- Widgets, a Reminders setting); its scale and place are gone (the column
	-- has its own place, sized with Edit Layout's wheel)
	if db.overlayLock == true then
		local rdb = MelloUI:GetModuleDB("Reminders")
		if rdb then
			rdb.widgetLock = true
		end
	end
	db.overlayLock, db.overlayScale = nil, nil
	db.overlayPoint, db.overlayRelativePoint, db.overlayX, db.overlayY = nil, nil, nil, nil
	if MelloUI.GetPosition and MelloUI:GetPosition("voiceOverlay") then
		MelloUI:ForgetPosition("voiceOverlay")
	end
	RefreshVoices()
end

function M:OnEnable(db)
	self.db = db
	-- Record Dialog Lines went off by default (user, 2026-09-24): every
	-- install had it on from the old default, so switch it off once; a
	-- player who wants it turns it back on and it stays
	if not db.collectLinesOffOnce then
		db.collectLinesOffOnce = true
		db.collectLines = false
	end
	RefreshVoices()
	npcLookup = nil
	if not HasTTS() then
		MelloUI:Print("Voice Over: this client has no text-to-speech API; the module will do nothing.")
		return
	end
	Widget:Register()
	ApplyReadButton()
	for _, event in ipairs(EVENTS) do
		pcall(eventFrame.RegisterEvent, eventFrame, event)
	end
	if db.collectLines then
		-- Create the store now so the saved file shows an empty table (the
		-- collector is running) rather than nothing at all.
		Collected()
	end
	if db.soundPacks then
		-- The packs' lookup tables are a few megabytes of Lua; load them a
		-- moment after login rather than inside the first dialog. Only the
		-- current mode's: asking the mode loads MelloUI_VoicePack when it is
		-- installed, and the old packs load only without it (never in its
		-- mode); their load says once per account where to get it.
		C_Timer.After(3, function()
			if M.isEnabled and M.db.soundPacks and Mode() == "old" then
				LoadSoundPacks()
			end
		end)
	end
end

function M:OnDisable()
	for _, event in ipairs(EVENTS) do
		pcall(eventFrame.UnregisterEvent, eventFrame, event)
	end
	Stop()
	Widget:Unregister()
	if readButton then
		readButton:Hide()
	end
end

function M:OnSettingChanged(key, value, db)
	self.db = db
	if key == "maleVoice" or key == "femaleVoice" then
		-- Let the user hear the choice straight away.
		local female = key == "femaleVoice"
		SpeakSample(female and "This is the voice used for female characters." or "This is the voice used for male characters.", { female = female })
	elseif key:match("^voice_") then
		local groupKey = key:sub(7)
		for _, group in ipairs(RACE_GROUPS) do
			if group.key == groupKey then
				local race = group.races and next(group.races) or "other"
				SpeakSample("This is the voice used for " .. group.name:lower() .. ".", { race = race, female = false })
			end
		end
	elseif key:match("^overlay") then
		Widget:Update()
	elseif key == "questLog" then
		ApplyReadButton()
	elseif key == "readBooks" and not value then
		StopPages()   -- the book being read ends with the switch
	end
end

MelloUI:Profile("VoiceOver", "dialog events", eventFrame)
MelloUI:Profile("VoiceOver", "sound pack load", LoadSoundPacks)
MelloUI:Profile("VoiceOver", "line lookup + queue", Enqueue)
